public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int size = schema.getSerializedSize(message);
    out.write(varInt32ToByteArray(size));
    schema.write(message, out);
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    int startPos = buffer.writeVarint32(0);
    int size = schema.writeTo(buffer, message);
    buffer.setWritten(size + startPos);
    byte[] prefix = buffer.getWrittenBytes();
    buffer = LinkedBuffer.use(prefix);
    buffer.writeVarint32(buffer.size() - startPos);
    buffer.write(prefix, startPos, buffer.size() - startPos);
    out.write(buffer.getWrittenBytes());
    return buffer.size();
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    ByteArrayOutputStream byteArrayOut = new ByteArrayOutputStream();
    schema.writeTo(byteArrayOut, message, buffer);
    byte[] bytes = byteArrayOut.toByteArray();
    int messageSize = bytes.length;
    out.write(messageSize >>> 24);
    out.write((messageSize >>> 16) & 0xFF);
    out.write((messageSize >>> 8) & 0xFF);
    out.write(messageSize & 0xFF);
    out.write(bytes, 0, bytes.length);
    return messageSize;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    // Serialize the message using the provided schema and buffer
    ByteString serialized = schema.toByteArray(message);

    // Write the length of the serialized message as a varint
    int size = serialized.size();
    CodedOutputStream codedOut = CodedOutputStream.newInstance(buffer);
    codedOut.writeVarint32NoTag(size);

    // Write the serialized message to the output stream
    out.write(serialized.toByteArray());
    out.flush();

    // Return the size of the message
    return size;
}

public static <T> int writeDelimitedTo(OutputStream out, T message, Schema<T> schema, LinkedBuffer buffer) throws IOException {
    byte[] data = schema.toByteArray(message);
    int size = data.length;
    out.write(CodedOutputStream.computeRawVarint32Size(size));
    out.write(data, 0, size);
    return size;
}

