protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 3600000L; // 1 hour in milliseconds

    if (start >= end) {
        return timeRanges;
    }

    while (start < end) {
        long nextStart = start + fetchDataDuration;
        timeRanges.add(new TimeRange(start, Math.min(nextStart, end)));
        start = nextStart;
    }

    return timeRanges;
}

List<TimeRange> buildTimeRanges(long start, long end) {
    if (start < 0 || end < 0 || start > end) {
        throw new IllegalArgumentException("Invalid time range");
    }

    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDataDuration = 1000L; // Example value for FETCH_DATA_DURATION

    while (start < end) {
        long nextStart = Math.min(start + fetchDataDuration, end);
        timeRanges.add(new TimeRange(start, nextStart));
        start = nextStart;
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;
    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long currentTime = start;
        while (currentTime < end) {
            long nextTime = currentTime + FETCH_DATA_DURATION;
            if (nextTime > end) {
                nextTime = end;
            }
            timeRanges.add(new TimeRange(currentTime, nextTime));
            currentTime = nextTime;
        }
    }
    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long fetchDuration = FETCH_DATA_DURATION;

    if (end - start > fetchDuration) {
        long currentTime = start;
        while (currentTime + fetchDuration < end) {
            timeRanges.add(new TimeRange(currentTime, currentTime + fetchDuration));
            currentTime += fetchDuration;
        }
        timeRanges.add(new TimeRange(currentTime, end));
    } else {
        timeRanges.add(new TimeRange(start, end));
    }

    return timeRanges;
}

protected List<TimeRange> buildTimeRanges(long start, long end) {
    List<TimeRange> timeRanges = new ArrayList<>();
    long duration = end - start;

    if (duration <= FETCH_DATA_DURATION) {
        timeRanges.add(new TimeRange(start, end));
    } else {
        long remainingDuration = duration;
        long startTime = start;

        while (remainingDuration > 0) {
            long rangeDuration = Math.min(FETCH_DATA_DURATION, remainingDuration);
            long endTime = startTime + rangeDuration;

            timeRanges.add(new TimeRange(startTime, endTime));

            remainingDuration -= rangeDuration;
            startTime = endTime;
        }
    }

    return timeRanges;
}

