private String substituteVariables(String value, Properties props) {
    int startIndex = value.indexOf("${");
    while (startIndex != -1) {
        int endIndex = value.indexOf("}", startIndex);
        if (endIndex == -1) {
            break;
        }
        String variable = value.substring(startIndex + 2, endIndex);
        String replacement = props.getProperty(variable);
        if (replacement != null) {
            value = value.substring(0, startIndex) + replacement + value.substring(endIndex + 1);
