public static int writeTo(final DataOutput out, LinkedBuffer node) throws IOException {
    int totalSize = 0;
    while (node != null) {
        byte[] content = node.getData();
        int size = content.length;
        out.writeInt(size);
        out.write(content);
        totalSize += size;
        node = node.getNext();
    }
    return totalSize;
}

