public String format(final LoggingEvent event) {
    // Step 1: Check if the event is null
    if (event == null) {
        throw new IllegalArgumentException("LoggingEvent cannot be null");
    }

    // Step 2: Extract the logging details
    String loggerName = event.getLoggerName();
    LogLevel logLevel = event.getLevel();
    String message = event.getMessage();
    Throwable throwable = event.getThrowableInformation() != null ? event.getThrowableInformation().getThrowable() : null;

    // Step 3: Format the logging event
    StringBuilder formattedEvent = new StringBuilder();
    formattedEvent.append("Logger: ").append(loggerName).append(", Level: ").append(logLevel).append(", Message: ").append(message);

    // Step 4: Append the stack trace if available
    if (throwable != null) {
        formattedEvent.append(", Stack Trace: ").append(throwable);
    }

    return formattedEvent.toString();
}

