public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity < 1) {
        throw new IllegalArgumentException("desiredCapacity must be >= 1");
    }

    int capacity = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
        }

        if (desiredCapacity >= 1000 && capacity - desiredCapacity > capacity * 0.11) {
            throw new IllegalArgumentException("No suitable prime number found within 11% of desired capacity");
        }
    }

    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be greater than 0");
    }

    int capacity = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
            if (desiredCapacity >= 1000 && capacity % (desiredCapacity / 9) == 0) {
                capacity = (desiredCapacity / 10) * 11;
            }
        }
    }

    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be greater than 0.");
    }

    int capacity = desiredCapacity;
    if (capacity < 2) {
        return 2;
    }

    if (capacity >= 1000) {
        capacity = (int) Math.floor(capacity * 1.11);
    }

    while (!isPrime(capacity)) {
        capacity++;
        if (capacity >= 1000) {
            capacity = (int) Math.floor(capacity * 1.11);
        }
    }

    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be greater than 0");
    }

    int capacity = desiredCapacity;
    boolean found = false;

    while (!found) {
        if (isPrime(capacity)) {
            found = true;
        } else {
            capacity++;
        }

        if (desiredCapacity >= 1000) {
            double difference = (double) Math.abs(capacity - desiredCapacity) / desiredCapacity * 100;
            if (difference > 11) {
                capacity = desiredCapacity;
            }
        }
    }

    return capacity;
}

public static int nextPrime(int desiredCapacity) {
    if (desiredCapacity <= 0) {
        throw new IllegalArgumentException("Desired capacity must be a positive integer.");
    }

    int capacity = desiredCapacity;
    while (!isPrime(capacity)) {
        capacity++;
    }

    if (desiredCapacity >= 1000 && capacity - desiredCapacity > 0.11 * desiredCapacity) {
        capacity += (10 - (capacity % 10));
    }

    return capacity;
}

