private Map<String, Object> buildContent(JsonObject jsonObject) {
    Map<String, Object> content = new HashMap<>();
    for (String key : jsonObject.keySet()) {
        JsonElement element = jsonObject.get(key);
        if (element.isJsonObject()) {
            content.put(key, buildContent(element.getAsJsonObject()));
        } else if (element.isJsonArray()) {
            List<Object> arrayContent = new ArrayList<>();
            for (JsonElement jsonElement : element.getAsJsonArray()) {
                if (jsonElement.isJsonObject()) {
                    arrayContent.add(buildContent(jsonElement.getAsJsonObject()));
                } else {
                    arrayContent.add(jsonElement);
                }
            }
            content.put(key, arrayContent);
        } else {
            content.put(key, element);
        }
    }
    return content;
}

