protected GraphPath<V, E> edgeSetToTour(@NotNull Set<E> tour, @NotNull Graph<V, E> graph) {
    if (tour == null || tour.isEmpty()) {
        throw new IllegalArgumentException("Tour set cannot be null or empty");
    }

    if (graph == null) {
        throw new IllegalArgumentException("Graph cannot be null");
    }

    V start = null;
    V end = null;
    Map<V, E> edges = graph.getEdgeMap();

    for (E edge : tour) {
        if (end != null && !edges.containsKey(end)) {
            throw new IllegalArgumentException("Edge " + edge + " does not exist in the graph");
        }
        end = edges.get(edge);
        if (start == null) {
            start = edge.getSource();
        }
    }

    return new GraphPath<>(start, end, edges);
}

GraphPath<V, E> function(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph cannot be null");
    }

    List<E> edgeList = new ArrayList<>(tour);
    if (edgeList.isEmpty()) {
        return null;
    }

    V startVertex = edgeList.get(0).getEndpoint(graph.getEdgeSource(edgeList.get(0)));
    GraphPath<V, E> path = new Walk<V, E>(graph, startVertex, startVertex);

    for (E edge : edgeList) {
        path = path.extend(graph.getOpposite(path.getEndVertex(), edge));
    }

    return path;
}

